Here's a complete TCP/IP server implementation in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <errno.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define MAX_CLIENTS 5

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE] = {0};

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }
    printf("Socket created successfully\n");

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("Setsockopt failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;  // Accept connections from any IP
    server_addr.sin_port = htons(PORT);

    // Bind socket to address and port
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("Bind successful on port %d\n", PORT);

    // Listen for incoming connections
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("Server listening on port %d...\n", PORT);

    // Main server loop
    while (1) {
        // Accept incoming connection
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        printf("New connection from %s:%d\n", 
               inet_ntoa(client_addr.sin_addr), 
               ntohs(client_addr.sin_port));

        // Send welcome message
        const char *welcome_msg = "Welcome to the TCP server!\n";
        send(client_fd, welcome_msg, strlen(welcome_msg), 0);

        // Handle client communication
        while (1) {
            // Clear buffer
            memset(buffer, 0, BUFFER_SIZE);

            // Receive data from client
            ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

            if (bytes_received <= 0) {
                if (bytes_received == 0) {
                    printf("Client disconnected\n");
                } else {
                    perror("Receive failed");
                }
                break;
            }

            printf("Received: %s", buffer);

            // Check for quit command
            if (strncmp(buffer, "quit", 4) == 0) {
                printf("Client requested to quit\n");
                break;
            }

            // Echo back to client
            char response[BUFFER_SIZE + 20];
            snprintf(response, sizeof(response), "Server echo: %s", buffer);
            send(client_fd, response, strlen(response), 0);
        }

        // Close client connection
        close(client_fd);
        printf("Connection closed\n\n");
    }

    // Close server socket (unreachable in this example)
    close(server_fd);
    return 0;
}
```

Here's also a simple **TCP client** to test the server:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int client_fd;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE] = {0};
    char input[BUFFER_SIZE] = {0};

    // Create socket
    client_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (client_fd == -1) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);

    // Convert IP address from string to binary
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
        perror("Invalid address");
        close(client_fd);
        exit(EXIT_FAILURE);
    }

    // Connect to server
    if (connect(client_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(client_fd);
        exit(EXIT_FAILURE);
    }

    printf("Connected to server\n");

    // Receive welcome message
    recv(client_fd, buffer, BUFFER_SIZE, 0);
    printf("%s", buffer);

    // Main client loop
    while (1) {
        printf("Enter message (or 'quit' to exit): ");
        fgets(input, BUFFER_SIZE, stdin);

        // Send message to server
        send(client_fd, input, strlen(input), 0);

        if (strncmp(input, "quit", 4) == 0) {
            break;
        }

        // Receive response
        memset(buffer, 0, BUFFER_SIZE);
        recv(client_fd, buffer, BUFFER_SIZE, 0);
        printf("%s", buffer);
    }

    close(client_fd);
    return 0;
}
```

## Compilation and Usage:

1. **Compile the server:**
```bash
gcc -o server server.c
```

2. **Compile the client:**
```bash
gcc -o client client.c
```

3. **Run the server:**
```bash
./server
```

4. **In another terminal, run the client:**
```bash
./client
```

## Key Features:

1. **Server Features:**
   - Listens on port 8080
   - Accepts multiple clients (one at a time)
   - Echoes received messages back to clients
   - Handles client disconnections gracefully
   - Displays connection information

2. **Error Handling:**
   - Checks return values of all socket operations
   - Uses `perror()` for descriptive error messages
   - Properly closes sockets on errors

3. **Communication Protocol:**
   - Simple text-based protocol
   - Client can send "quit" to disconnect
   - Server echoes messages with "Server echo: " prefix

## Enhancements you can make:

1. **Multi-threaded server** to handle multiple clients simultaneously
2. **Non-blocking I/O** using `select()` or `poll()`
3. **SSL/TLS encryption** for secure communication
4. **Custom protocol** with message headers and types
5. **Logging** to files
6. **Configuration file** for server settings
7. **Signal handling** for graceful shutdown

